template<size_t N> bool matchLiveCode(const unsigned char* p,const unsigned char (&expected)[N]) {
 std::array<unsigned char,N> copy{};SIZE_T read=0;
 return ReadProcessMemory(GetCurrentProcess(),p,copy.data(),N,&read) && read==N && !std::memcmp(copy.data(),expected,N);
}
inline bool validateWeaponTreeCode(const unsigned char* image) {
 return matchLiveCode(image+0x13738B0,treeFilterCode) && matchLiveCode(image+0x197E8A0,equipmentLookupTailCode) && matchLiveCode(image+0x1374AF0,equipmentLookupBodyCode);
}
